    39	        layout: { collisionPolicy: "push-right", gap: 3 }, children: [{ id: "overview", kind: "diagram",
    40	          position: { column: 0, row: 0 }, collapsed: false, contentId: "overview", collapsedContentId: "overview-summary" }] }
