    46	export function insertGridDiagram(document: MappingGridDocument, parentId: string, box: GridBox, content: Diagram): MappingGridDocument {
    47	  const summaryId = `${content.id}-summary`;
    48	  let scene: LineGridScene = { ...document.scene, contents: { ...document.scene.contents, [content.id]: content,
    49	    [summaryId]: createStoredDiagram({ id: summaryId, revision: 0, ascii: `[${content.content.ascii.split("\n")[0].trim().slice(0, 36)}]` }).diagram } };
    50	  scene = updateGridBox(scene, parentId, (parent) => {
    51	    if (parent.kind !== "container") throw new Error("Diagrams must be inserted into a container");
    52	    return { ...parent, collapsed: false, children: [...parent.children, { ...box, collapsedContentId: summaryId }] };
    53	  });
    54	  return { ...document, scene: layoutScene(scene, box.id), sections: { ...document.sections, [content.id]: [] } };
    55	}
